import { cacheLife, cacheTag } from 'next/cache'

import { getAllProducts } from './db'

export type Product = {
  id: number
  name: string
  price: number
}

/**
 * The cache tag shared by every catalog read. Invalidating it refreshes all
 * views built on this data, not just the admin page.
 */
export const PRODUCTS_TAG = 'products'

/**
 * Cached catalog read. The browsing path never hits the database: entries live
 * until the `products` tag is invalidated by a sync, so `max` avoids pointless
 * time-based recomputation for data that only changes when the ERP/PIM does.
 */
export async function getProducts(): Promise<Product[]> {
  'use cache'
  cacheTag(PRODUCTS_TAG)
  cacheLife('max')

  return getAllProducts()
}

/**
 * Kick off the upstream ERP/PIM sync and return as soon as it is accepted.
 * A sync can touch thousands of SKUs, so the admin request must not wait for
 * it to finish — the caller invalidates the `products` tag instead.
 */
export async function startCatalogSync(): Promise<void> {
  // Replace with the real enqueue call (job queue, webhook, ERP/PIM client).
  await Promise.resolve()
}

